				end
				updatePreview()
			end)
			Creator.AddSignal(redInput.Input.FocusLost, function(enterPressed)
				if enterPressed then
					local rgb = getRGB()
					local success, color = pcall(Color3.fromRGB, redInput.Input.Text, rgb.G, rgb.B)
