						end
					end
				end
				updatePreview()
			end)
			Creator.AddSignal(greenInput.Input.FocusLost, function(enterPressed)
				if enterPressed then
					local rgb = getRGB()
					local success, color = pcall(Color3.fromRGB, rgb.R, greenInput.Input.Text, rgb.B)
